def __tf_tensor__(
    self, dtype: Optional[dtypes.DType] = None, name: Optional[str] = None
    ) -> "Tensor":
  if dtype is not None and not dtype.is_compatible_with(self.dtype):
    raise ValueError(
        _add_error_prefix(
            f"Tensor conversion requested dtype {dtype.name} "
            f"for Tensor with dtype {self.dtype.name}: {self!r}",
            name=name))
  return self

def __tf_tensor__(
    self, dtype: Optional[dtypes.DType] = None, name: Optional[str] = None
    ) -> tensor_lib.Tensor:
  if not context.executing_eagerly():
    graph = get_default_graph()
    if not graph.building_function:
      raise RuntimeError(
          _add_error_prefix(
              "Attempting to capture an EagerTensor without "
              "building a function.",
              name=name))
    return graph.capture(self, name=name)
  return super().__tf_tensor__(dtype, name)

def __getattr__(self, *args, **kwargs):
  # Fallback to `__getattr__` if `__getattribute__` fails, so that we can
  # directly expose Tensor's methods.
  return getattr(self.tensor, *args, **kwargs)

